from pathlib import Path
import json,sys,re
O=Path(__file__).resolve().parent;B=next(p for p in O.parents if p.name=='legal-rewrite');sys.path.insert(0,str(B));from substantive_impact import plain
ss=json.loads((O/'source.json').read_text());by={s['number']:s for s in ss};aa=[]
P=lambda x:'<p>'+x+'</p>\n'
repeal=P('Le présent article est abrogé à compter de l’entrée en vigueur de la loi portant suppression de la déclaration de mise en location prévue au chapitre IV du titre III du livre VI.')
texts={
'L634-1':repeal+P('À compter de cette date, aucune zone ni délibération prise sur le fondement du présent chapitre ne peut imposer une déclaration de mise en location. Les obligations de mise en œuvre, de suivi et de rapport annuel propres à ce dispositif cessent, y compris pour les délégations en cours, sans déclaration ni rapport de clôture de remplacement.')+P('Cette suppression ne modifie pas le régime distinct de l’autorisation préalable prévu au chapitre V, les obligations de décence, de sécurité ou de salubrité, les diagnostics et informations dus aux locataires, ni les pouvoirs de police et les droits des occupants qui reposent sur un autre fondement. Les contrats valablement conclus, aides attribuées, droits acquis, créances légalement nées et recours ne sont pas remis en cause, sous réserve des dispositions plus favorables de l’article L. 634-4.'),
'L634-2':repeal+P('La transmission aux organismes payeurs des délibérations propres à ce dispositif n’est plus requise à compter de cette date, y compris lorsqu’elle n’a pas encore été accomplie pour une délibération antérieure. Les transmissions et décisions régulièrement accomplies ne sont pas annulées. Les échanges nécessaires aux aides, à la décence ou à une police de sécurité ou de salubrité conservent leur fondement propre ; aucune déclaration ni transmission de substitution n’est créée.'),
'L634-3':repeal+P('À compter de cette date, aucune déclaration de mise en location, annexe de diagnostic destinée à cette seule déclaration, régularisation ou nouvelle déclaration après changement de locataire n’est exigée sur le fondement du présent chapitre, même si le bail a été conclu auparavant. Aucune copie du récépissé de ce dispositif n’a à être remise au locataire.')+P('L’absence de déclaration reste sans effet sur le bail dont bénéficie le locataire. Le paiement en tiers payant des aides personnelles au logement ne peut plus être subordonné au dépôt de cette déclaration ni à la production de son récépissé, y compris pour les demandes en cours. Les autres conditions d’attribution et de paiement des aides demeurent applicables ; aucune aide acquise ni restitution légalement due n’est supprimée.')+P('Le dossier de diagnostic technique, les informations dues au locataire et les obligations de décence prévus par la loi n° 89-462 du 6 juillet 1989 demeurent applicables selon leur champ propre. Les formalités et décisions du chapitre V ainsi que les polices de sécurité et de salubrité ne sont pas supprimées par le présent article.'),
'L634-4':repeal+P('Aucune amende nouvelle ne peut être prononcée sur le seul fondement d’un défaut de déclaration prévu au présent chapitre, y compris pour un manquement antérieur. Les procédures de sanction non définitivement jugées prennent fin selon les règles d’application de la loi répressive plus douce ; aucune régularisation déclarative n’est requise pour en bénéficier.')+P('Les amendes devenues définitives avant cette date et restant légalement exigibles conservent leur régime de recouvrement, de prescription, de restitution et de recours, sans remboursement général des sommes déjà versées. Cette disposition ne fait pas obstacle aux règles répressives plus favorables applicables aux sanctions en cause. Les sanctions et mesures fondées sur des manquements distincts à la décence, à la sécurité ou à la salubrité ne sont pas supprimées.'),
'L634-5':repeal+P('Aucun décret pris pour l’application du présent chapitre ne peut maintenir ou rétablir, pour l’avenir, la déclaration supprimée, ses annexes, son récépissé, ses rapports ou ses sanctions. Les mesures strictement nécessaires au traitement des créances et recours antérieurs conservés par l’article L. 634-4 restent possibles selon leurs règles, sans obligation déclarative ou rapport périodique de remplacement.'),
'R634-1':repeal+P('Les mises en location relevant antérieurement du titre Ier ou du titre Ier bis de la loi n° 89-462 du 6 juillet 1989 ne sont plus soumises à la déclaration du chapitre IV, sans distinction entre une nouvelle location, une reconduction, un renouvellement ou un avenant. Les diagnostics, les droits des locataires et les obligations autonomes de décence restent applicables. La définition des opérations soumises au chapitre V reste distincte.'),
'R634-2':repeal+P('Aucun formulaire ni relevé des identités, coordonnées, mandats ou caractéristiques du logement ne peut être exigé sur le seul fondement de cet article, y compris pour compléter une déclaration antérieure. Les données déjà recueillies restent soumises à leur régime légal de conservation et d’accès ; aucun accès ou traitement nouveau n’est autorisé. Les informations exigibles sur un fondement autonome ne sont pas supprimées.'),
'R634-3':repeal+P('Les déclarations en cours n’appellent plus de récépissé, de demande de complément ou de nouveau dépôt au titre du dispositif supprimé. Le déclarant ne peut être tenu de fournir les pièces ou informations manquantes ni de recommencer sa déclaration, même si un délai avait été fixé avant cette date. Les récépissés déjà délivrés et les actes valablement accomplis conservent leur valeur historique, sans nouvelle certification et sans conditionner le tiers payant des aides.'),
'R634-4':repeal+P('Aucune invitation à régulariser une déclaration ou à en produire le récépissé ne peut être imposée pour le traitement des procédures non définitives de sanction du dispositif supprimé. Les observations et recours déjà présentés conservent leurs effets dans le cadre de la transition prévue à l’article L. 634-4 ; aucune nouvelle formalité n’est exigée pour bénéficier de la loi répressive plus douce.'),
'R634-5':repeal+P('Aucun titre de recette nouveau ne peut être émis pour une amende qui ne demeure pas légalement exigible dans les conditions de l’article L. 634-4. Le recouvrement des seules amendes antérieures définitives qui restent dues, ainsi que les restitutions, prescriptions et recours, relève des règles applicables aux créances de la commune ou de l’établissement public de coopération intercommunale bénéficiaire, notamment de l’article L. 1617-5 du code général des collectivités territoriales. Aucun rapport annuel de délégation ni rapport de clôture de remplacement ne subsiste au titre du présent article.'),
}
# Les passages sources maintenus restent littéralement entiers ; seuls les changements expressément décrits sont effectués.
x=by['L635-1']['source_xml'];x=x.replace("en application de l'article L. 351-2","au sens de l'article L. 831-1");x=x.replace('soumises à déclaration de mise en location','soumises à autorisation préalable de mise en location');old="Le maire de chaque commune délégataire adresse à l'établissement public de coopération intercommunale à fiscalité propre un rapport annuel sur l'exercice de cette délégation.";assert old in x;x=x.replace(old,"Aucun rapport annuel propre à l’exercice de cette délégation n’est exigé. Les contrôles et les transmissions prévus par les autres articles du présent chapitre demeurent applicables.")
x+=P('La suppression du rapport annuel s’applique aux délégations en cours et aux rapports non encore transmis à la date d’entrée en vigueur de la loi portant cette suppression, sans rapport de remplacement. Elle ne retire aucune compétence de contrôle, ne modifie pas les conditions des aides ni les droits des occupants et ne remet pas en cause les engagements valablement conclus. Les logements conventionnés qui bénéficiaient de la dispense d’autorisation préalable restent dispensés dans les conditions conventionnelles qui leur sont applicables ; la coordination avec l’article L. 831-1 ne restreint pas cette dispense.')
texts['L635-1']=x
x=by['L635-4']['source_xml'];old="L'autorisation préalable de mise en location doit être renouvelée à chaque nouvelle mise en location.";assert old in x;x=x.replace(old,"L’autorisation préalable de mise en location demeure valable pour les mises en location successives du même logement et n’a pas à être renouvelée au seul motif d’un changement de locataire ou de propriétaire. Le seul fait qu’elle ne soit pas suivie d’une mise en location dans les deux ans de sa délivrance n’entraîne pas sa caducité. Elle ne dispense pas du respect, pour chaque location, des conditions de décence, de sécurité et de salubrité applicables ni de l’exécution des travaux prescrits. Elle ne peut permettre une occupation interdite par une mesure de police. Les pouvoirs de police et les droits des occupants demeurent applicables indépendamment de cette autorisation.")
x+=P('La dispense de renouvellement et la suppression de la caducité fondée sur le seul délai de deux ans s’appliquent dès l’entrée en vigueur de la loi qui les prévoit aux autorisations expresses ou tacites encore valables, y compris celles délivrées antérieurement. Elles ne sont pas subordonnées à l’entrée en vigueur d’un décret. Les demandes de renouvellement en cours pour ce seul motif cessent d’être nécessaires, sans nouveau dépôt ni remise à zéro d’un délai utile. Les autorisations déjà devenues caduques ou retirées avant cette date ne sont pas rétablies par cette disposition. Les prescriptions, refus, mesures de police et droits des occupants conservent leurs effets ; aucune autorisation ne vaut certificat permanent de décence.')
texts['L635-4']=x
x=by['R635-3']['source_xml'];old="L'autorisation devient caduque s'il apparaît qu'elle n'est pas suivie d'une mise en location dans un délai de deux ans suivant sa délivrance.";assert old in x;x=x.replace(old,"L’absence de mise en location dans les deux ans suivant la délivrance n’entraîne pas la caducité de l’autorisation. La validité pour les mises en location successives et les protections de fond sont celles prévues à l’article L. 635-4.")
old="En cas de mutation à titre gratuit ou onéreux du logement, une autorisation en cours de validité peut être transférée au nouveau propriétaire du logement. Ce transfert prend effet à compter du dépôt par le nouveau propriétaire, auprès de l'autorité compétente, d'une déclaration de transfert, sous réserve de l'accord du bénéficiaire initial de l'autorisation. La déclaration de transfert est établie conformément à un formulaire dont le modèle est fixé par arrêté du ministre chargé du logement et déposée selon des modalités définies par l'autorité compétente mentionnée au I de l'article L. 635-1.";assert old in x;x=x.replace(old,"En cas de mutation à titre gratuit ou onéreux du logement, une autorisation en cours de validité bénéficie de plein droit au nouveau propriétaire, sans déclaration de transfert, formulaire ni accord supplémentaire du bénéficiaire initial. Ce bénéfice ne modifie ni les conditions civiles de la mutation ni les droits réels ou personnels des tiers. Les prescriptions attachées au logement, les mesures de police et les droits des occupants restent applicables.")
# La référence procédurale défectueuse sera tranchée après lecture primaire ; aucun renvoi substitué par conjecture.
x=x.replace('L. 112-3, R. 112-5 et R. 112-6','L. 112-3 et R. 112-5')
x=x.replace('vaut récépissé de demande d\'autorisation.','vaut récépissé de demande d\'autorisation. Pour les demandes légalement adressées par voie électronique, l’accusé de réception électronique prévu aux articles L. 112-11 et R. 112-11-1 du même code vaut ce récépissé. Les garanties de recours prévues aux articles L. 112-6 ou L. 112-12 de ce code demeurent applicables dans leurs champs respectifs. Le présent article ne rend obligatoire aucune voie électronique de dépôt.')
x=x.replace('<div align="left">','<div>')
x+=P('La suppression de la caducité fondée sur le seul délai de deux ans résulte de l’article L. 635-4 et s’applique depuis l’entrée en vigueur de la loi qui la prévoit aux autorisations encore valables à cette date, sans attendre le présent décret. Aucune caducité ne peut leur être opposée sur ce seul fondement entre l’entrée en vigueur de cette loi et celle du décret. Les autorisations déjà caduques ou retirées avant l’entrée en vigueur de cette loi ne sont pas rétablies ; les retraits régulièrement prononcés sur un autre fondement restent applicables. La suppression de la déclaration de transfert s’applique aux autorisations en cours de validité à l’entrée en vigueur du décret qui la prévoit ainsi qu’aux mutations postérieures ; les déclarations de transfert en cours deviennent sans objet sans dépôt de remplacement. Les transferts régulièrement accomplis restent valables. Aucun contrôle de remplacement ni certificat nouveau n’est institué.')
texts['R635-3']=x
x=by['R635-5']['source_xml'];x=x.replace("dans les conditions prévues par l'article R. 2342-4 du code général des collectivités territoriales","selon les dispositions applicables aux créances des collectivités territoriales et de leurs établissements publics, notamment l’article L. 1617-5 du code général des collectivités territoriales")
old="<p>En cas de mise en œuvre de la délégation prévue au III de l'article L. 635-1, le rapport annuel sur l'exercice de cette délégation comprend des informations sur le recouvrement de cette amende et le montant recouvré.</p>";assert old in x;x=x.replace(old,P('Aucun rapport annuel de délégation propre à ce recouvrement n’est exigé. Cette suppression ne modifie ni les comptes, ni les contrôles, ni les pièces de recouvrement légalement nécessaires sur un autre fondement, ni les droits de contestation du débiteur.'))
