M_DECL='location-declaration-posterieure-supprimee';M_REPORT='location-permis-rapport-delegation-supprime';M_VALID='location-permis-validite-durable';M_TRANSFER='location-permis-transfert-sans-formalite';M_REF='location-permis-renvois-proceduraux-coherents'
reasons={
'L634-1':'Supprime le régime de déclaration postérieure et son zonage, suivi délégué et rapport exclusifs ; le permis ciblant l’habitat dégradé et les polices restent distincts.',
'L634-2':'Coordonne la fin de la déclaration en retirant sa transmission de délibérations aux organismes payeurs ; les échanges autonomes utiles aux aides demeurent.',
'L634-3':'Supprime le dépôt après chaque bail, sa copie de diagnostics et de récépissé, les renouvellements et la condition de récépissé pour le tiers payant ; conserve bail, aides et protections de fond.',
'L634-4':'Supprime les seules sanctions pour défaut de déclaration abolie, avec loi plus douce et conservation bornée des anciennes amendes définitives légalement exigibles.',
'L634-5':'Ferme l’habilitation réglementaire propre au régime aboli ; aucune déclaration ou rapport de substitution ne peut être recréé.',
'R634-1':'Coordonne le champ réglementaire avec la suppression législative de la déclaration ; aucune opération anciennement dispensée ne devient soumise au permis par ce texte.',
'R634-2':'Retire le formulaire et ses quatre rubriques exclusivement déclaratives ; aucune nouvelle collecte ou extension de l’accès aux données.',
'R634-3':'Met fin au circuit récépissé, complément et redépôt du dispositif aboli, y compris pour les dossiers incomplets en cours.',
'R634-4':'Retire la procédure de régularisation du seul défaut déclaratif aboli, sans retirer les observations et recours anciens.',
'R634-5':'Coordonne la fin des amendes déclaratives et rapports de recouvrement ; les seules créances antérieures définitives encore dues restent recouvrables selon le droit commun, sans renvoi à R2342-4 abrogé.',
'L635-1':'Retire le rapport annuel propre à la délégation du permis ; préserve zonage ciblé, six mois, compétences et dispenses des logements sociaux/conventionnés. Corrige le renvoi L351-2 conformément à sa note DILA et la mention déclaration au III.',
'L635-4':'Supprime une demande et une décision répétées au seul changement de locataire/propriétaire pour un logement déjà autorisé et la caducité fondée sur le seul délai de deux ans dès la loi, sans attendre le décret ; conserve premier dossier, diagnostics, récépissé et accord tacite sous un mois, sécurité et droits des occupants.',
'R635-3':'Retire la caducité automatique de deux ans sans mise en location et la déclaration de transfert à chaque mutation ; conserve réception, contenu de la décision, droits privés et prescriptions. Corrige seulement le renvoi procédural non opérant après contrôle primaire.',
'R635-5':'Coordonne le rapport annuel supprimé au législatif et remplace le renvoi R2342-4 abrogé par les règles de recouvrement des collectivités ; montants, bénéficiaires, délai et recours restent.',
}
needed={
'L635-3':'Le permis dans les seules zones d’habitat dégradé empêche la location dangereuse ; refus motivé avec travaux, visite de6à21h et autorisation du juge en cas de refus/inaccessibilité protègent logement et domicile. L’autorisation durable deL635-4 satisfait toujours la première condition de délivrance.',
'L635-5':'L’annexion de l’autorisation au bail informe le nouveau locataire des prescriptions du logement. Garder une copie de l’autorisation existante ne rétablit ni son renouvellement ni une déclaration publique ; supprimer cette information ne paraît pas justifié par le dossier étudié.',
'L635-6':'La transmission du refus àCAF/MSA/fisc relie le constat individualisé de non-décence aux contrôles autonomes des aides et évite qu’un refus de louer soit invisible. Aucun second dossier du bailleur ni délai d’attente supplémentaire n’est créé par ce texte.',
'L635-7':'Les amendes ne portent que sur l’absence de première demande légalement nécessaire ou la location malgré refus, avec contradictoire, proportionnalité et prescriptionunan. Une location dispensée de nouvelle demande parL635-4 ne remplit pas ces manquements ; pas de sanction nouvelle ni hausse des plafonds5000/15000€.',
'L635-8':'L’irrégularité du permis ne peut effacer le bail ni les droits du locataire ; l’accord tacite ne prouve pas la décence. Ces deux garanties restent nécessaires lorsque l’autorisation devient durable, sans nouveau certificat opposable au locataire.',
'L635-9':'Le permis est inopposable aux polices et aux droits des occupants ; un arrêté d’insalubrité/péril/équipements communs interdit la délivrance. Ces garanties empêchent que la validité prolongée autorise une occupation interdite, sans créer une formalité supplémentaire.',
'L635-10':'Le signalement des refus et réserves au comité du plan et à l’observatoire concerne les seuls logements ayant fait l’objet d’une décision motivée, pour le suivi du traitement de l’habitat indigne. Il ne faut pas confondre ce suivi utile avec la déclaration générale de chaque bail abolie.',
'R635-1':'Le champ titresI/Ibis exclut expressément reconduction, renouvellement et avenant. Ces dispenses favorables restent intégrales ; la conservation n’impose aucune demande répétée contraire àL635-4, qui retire en plus le seul changement de locataire pour un logement déjà autorisé.',
'R635-2':'Les quatre rubriques de la première demande identifient le bailleur/mandataire et le logement à visiter ; elles n’imposent aucune pièce d’état civil distincte. Leur utilité subsiste pour un permis initial ciblé ; aucune nouvelle demande n’est exigée au seul changement de propriétaire.',
'R635-4':'Le mois pour observations et régularisation avant sanction protège la défense ; joindre le récépissé concerne la seule première demande encore nécessaire. Les demandes dispensées parL635-4/R635-3 ne deviennent pas obligatoires par cette procédure ; la suppression des recours ne serait pas une simplification légitime.',
}
def ef(kind,mid,sq,pq,before,after,description):return {'kind':kind,'measure_id':mid,'description':description,'before':before,'after':after,'unit':'legal_duty','affected_population':'Bailleurs et collectivités entrant exactement dans le régime de l’article ; occupants et aides protégés.','conditions_and_transition':'Entrée en vigueur de la loi ou du décret proposé, sans date de promulgation inventée ; droits, décisions et créances antérieurs selon les transitions expresses.','replacement_or_new_burdens':'Aucune déclaration, rapport, certification ou taxe de remplacement ; contrôles autonomes et pièces réellement nécessaires conservés. Coût public net non chiffré.','source_quote':sq,'proposed_quote':pq}
for s in ss:
 n=s['number'];changed=n in texts;body=texts.get(n);cls='retained_necessary'if not changed else ('material_reduction'if n in ['L634-1','L634-3','L635-1','L635-4','R635-3']else'coordination_only');reason=reasons.get(n,needed.get(n));assert reason
 row={k:s[k]for k in ['code_id','source_id','source_sha256','number']};row.update(status='rewrite_draft'if changed else'retained_unchanged',proposed_xml=body,reason=reason,review_notes='Sources XML et notes DILA intégralement lues ; dispositions maintenues et renvois comparés aux cibles capturées. '+reason+' Les avantages, conditions de fond et transitions sont détaillés dans l’audit. Aucune validation par juriste, aucun gain national chiffré. Les arrêtés de formulaires et les plateformes hors cinq codes restent à adapter sans rétablir le régime supprimé.')
 if n in ['L634-1','L635-1']:row['review_notes']+=' La note non vide de2019 transpose L351-2 vers L353-1/L821-2/L831-1/L831-2 ; ces quatre corps ont été lus. Le lien générique aux tables de fonction publique ajouté dans la note n’est pas une norme locative à transposer.'
 if n=='R635-3':row['review_notes']+=' L112-3/R112-5 CRPA entiers décrivent l’accusé ; le corpus primaire2025 duCRPA ne contient aucunR112-6en vigueur, alors queL112-6entier porte les garanties de recours. Seul le renvoiR112-6est retiré ; ces garanties légales ne sont ni supprimées ni remplacées par une autorisation. Le retrait de ce renvoi impropre et la réception électronique sont coordination_only, sans gain supplémentaire. L112-11entierdanssaversion2016/index2026 écarte L112-3/L112-6 pour son champ ; R112-11-1entier etL112-12entier précisent mentions etrecours électroniques. La voie légalement admise reste facultative au titre duprésentarticle. Le seul attribut HTMLalign deprésentation aété retiré sanschanger letexte.'
 if n=='R635-5':row['review_notes']+=' R2342-4 CGCT est abrogé au1janvier2026, pas réactivé ; seul le fondement général de recouvrementL1617-5 est cité après lecture intégrale.'
 row['benefit_review']='Les logements sociaux et conventionnés dispensés restent hors permis ; la déclaration est supprimée pour tous, sans assujettir les anciens exemptés. Les reconductions, renouvellements, avenants, accord tacite sousunmois, baux et aides restent protégés. '+('Les sanctions non définitives bénéficient de la loi plus douce ; pas de remboursement général des amendes définitives légalement dues.'if'634'in n else'La dispense future de renouvellement et le transfert sans formalité ne retirent ni décence, ni santé, ni protection du domicile, ni droits privés. Aucune condition nouvelle aux aides.')
 effects=[]
 if n=='L634-1':effects=[ef('obligation_removed',M_DECL,"peut délimiter des zones soumises à déclaration de mise en location","aucune zone ni délibération prise sur le fondement du présent chapitre ne peut imposer une déclaration de mise en location",'Régime local facultatif imposant un dépôt après chaque nouveau bail.','Régime déclaratif supprimé ; permis ciblé et polices distincts conservés.','Suppression du dispositif déclaratif et de son circuit propre, une seule famille pour dix articles.')]
 elif n=='L634-3':effects=[ef('obligation_removed',M_DECL,'Cette déclaration est renouvelée à chaque nouvelle mise en location.','aucune déclaration de mise en location, annexe de diagnostic destinée à cette seule déclaration, régularisation ou nouvelle déclaration après changement de locataire n’est exigée','Déclaration15jours aprèschaquebail, diagnostics/recépissé etconditiontierspayant.','Aucun dépôt ni récépissé déclaratif ; aides sanscettecondition.','Exécution de la même suppression déclarative, pas une économie supplémentaire par pièce/locataire.')]
